export const DEFAULT_EMBLEM = 'quill-ink';
export const emblemKey = (key) => (key && EMBLEMS[key] ? key : DEFAULT_EMBLEM);

/** SVG del emblema (hereda el color con currentColor). */
export function emblemSvg(key, { cls = '', label = '' } = {}) {
  const [name, , d] = EMBLEMS[emblemKey(key)];
  const a11y = label ? `role="img" aria-label="${label === true ? name : label}"` : 'aria-hidden="true"';
  return `<svg class="emblem-svg ${cls}" viewBox="0 0 512 512" ${a11y}><path fill="currentColor" d="${d}"/></svg>`;
}
